async (request) => {
        const { execution_context } = request;
        const program_context = execution_context.getProgramContext();
        const program = common$1.ProgramBuilder.create("inventory$ExecuteInventorySlipSaveProgram" /* EN_PROGRAM_ID.ExecuteInventorySlipSaveProgram */, execution_context);
        const result = await program.executeAsync({});
        if (!result) {
            return;
        }
        // ======================================================================================================
        // 4. 결과 처리
        // ======================================================================================================
        const dmc = program_context.data?.dmc_map?.[common_.CurrentUtil.getModelInfo(execution_context, "master" /* EN_INPUT_MENU_TYPE.Master */)?.model_id ?? ''];
        const input_data_model_id = dmc.data_model_id;
        // ======================================================================================================
        // 5. 임시저장 데이터 삭제
        // ======================================================================================================
        const temporarySaveFeature = execution_context.tryGetFeature("ITemporarySaveFeature$temporary_save" /* EN_FEATURE_ID_TEMP.ITemporarySaveFeature */);
        temporarySaveFeature?.deleteTemp();
        // ======================================================================================================
        // 6. 페이지 이동
        // ======================================================================================================
        const { vmc } = execution_context.getProgramContext().data;
        const menu_attr_request = execution_context.attr
            .createRequestBuilder()
            .setPAttrOwner("menu" /* EN_P_ATTR_OWNER.menu */)
            .setAttrId(['save_action_mode'])
            .build();
        const save_action_mode = execution_context.attr.get(menu_attr_request)?.data;
        await _pageMovement(vmc, save_action_mode, result.data_model?.[input_data_model_id][0]);
        async function _pageMovement(vmc, action_mode, res_data_model) {
            const { use_tf, barcode_focus_list, barcode_list } = _getBarcodeInfo();
            // 보류적용일경우 신규로 취급
            if (execution_context.routeConfig.pageRouteOptions?.param?.action_mode) {
                if (_.isEqual(execution_context.routeConfig.pageRouteOptions?.param?.action_mode, "USE_HOLD" /* EN_ACTION_MODE.UseHold */)) {
                    execution_context.routeConfig.pageRouteOptions.param.action_mode = "GET_CREATE" /* EN_ACTION_MODE.GetCreate */;
                }
            }
            const option = {
                reqData: {
                    ...execution_context.routeConfig.pageRouteOptions.reqData,
                    barcode_option: { use_tf },
                },
                preserve: {
                    options: {
                        barcode_option: {
                            use_tf,
                            barcode_focus_list,
                            barcode_list,
                        },
                    },
                },
            };
            switch (action_mode) {
                case "NEW" /* EN_ACTION_MODE.Create */:
                    await _createPageMovement(vmc, option, res_data_model);
                    break;
                case "UPDATE" /* EN_ACTION_MODE.Modify */:
                    await _modifyPageMovement(vmc, option);
                    break;
            }
        }
        async function _createPageMovement(vmc, option, res_data_model) {
            await execution_context
                .getFeature("IHandleRouteFeature$V56" /* EN_FEATURE_ID.IHandleRouteFeature */)
                .reloadPageAsync(option);
            // to-do 현재는 TP에 대한 임시처리 추가 작업 필요
            if (_.vIsEquals(execution_context.routeConfig.pageLoadOptions.pageType, 'POPUP') ||
                _.vIsEquals(execution_context.routeConfig.pageLoadOptions.popupOptions?.popupType, 'WINDOW')) {
                if (execution_context.routeConfig.pageLoadOptions.is_from_approval) {
                    await _ApprovalSlip(vmc, res_data_model);
                }
                else if (execution_context.routeConfig.pageRouteOptions?.param?.IsRefNew) {
                    await _AttachSlip(vmc, res_data_model);
                }
                else {
                    vmc.sendMessage({
                        redraw: true,
                        is_from_order_mng: execution_context.routeConfig.pageRouteOptions.param.is_from_order_mng ?? false, // ! 기존 pageLoadOptions.data_map 에서 받던 것 pageRouteOptions.param 으로 받도록
                        is_from_order_proc: execution_context.routeConfig.pageRouteOptions.param.is_from_order_proc ?? false, // ! 기존 pageLoadOptions.data_map 에서 받던 것 pageRouteOptions.param 으로 받도록
                    });
                }
            }
        }
        async function _modifyPageMovement(vmc, option) {
            const bizz_name = program_context.sourceData.bizz?.bizz_name;
            await execution_context
                .getFeature("IHandleRouteFeature$V56" /* EN_FEATURE_ID.IHandleRouteFeature */)
                .reloadPageAsync({
                preserve: option.preserve,
                param: {
                    bizz_sid: program_context.data.bizz_sid,
                    menu_sid: program_context.data.menu_sid,
                    action_mode: "GET_CREATE" /* EN_ACTION_MODE.GetCreate */,
                },
                reqData: {
                    ...option.reqData,
                    menu_nm: common_.DataModelUtil.resolveResource(`@{${'rex04326'}([${bizz_name}])}`),
                },
            });
            if (_.vIsEquals(execution_context.routeConfig.pageLoadOptions.pageType, 'POPUP')) {
                vmc.sendMessage({
                    redraw: true,
                    is_from_order_mng: execution_context.routeConfig.pageRouteOptions.param.is_from_order_mng ?? false, // ! 기존 pageLoadOptions.data_map 에서 받던 것 pageRouteOptions.param 으로 받도록
                    is_from_order_proc: execution_context.routeConfig.pageRouteOptions.param.is_from_order_proc ?? false, // ! 기존 pageLoadOptions.data_map 에서 받던 것 pageRouteOptions.param 으로 받도록
                });
            }
        }
        function _getBarcodeInfo() {
            const barcode_state = vmc.getPropState("DynamicMiddleButtonModel" /* EN_BUTTON_DEFINITION_ID.DynamicMiddleButtonModel */, 'barcode');
            const barcode_use_tf = barcode_state?.is_active ?? false;
            const barcode_focus_list_state = _.find(barcode_state?.sibling_items, (item) => item.id === 'barcode_focus_list');
            const barcode_list_state = _.find(barcode_state?.sibling_items, (item) => item.id === 'barcode_list');
            return {
                use_tf: barcode_use_tf,
                barcode_focus_list: barcode_focus_list_state?.display_value,
                barcode_list: barcode_list_state?.display_value,
            };
        }
        async function _AttachSlip(vmc, res_data_model) {
            const attach_slip_message = await common$1.SvcCommandBuilder.create(GetAttachSlipMessageSvc, execution_context).executeAsync({
                execution_context,
                dmc,
                res_data_model,
            });
            vmc.sendMessage(attach_slip_message);
        }
        async function _ApprovalSlip(vmc, res_data_model) {
            const approval_slip_message = await common$1.SvcCommandBuilder.create(GetApproveSlipMessageSvc, execution_context).executeAsync({
                execution_context,
                dmc,
                res_data_model,
            });
            vmc.sendMessage(approval_slip_message);
        }
    }

async (request) => {
        const { execution_context } = request;
        const route_handler = execution_context.getFeature("IHandleRouteFeature$V56" /* EN_FEATURE_ID.IHandleRouteFeature */);
        const program_context = execution_context.getProgramContext();
        const model_id = _.vSafe(common_.CurrentUtil.getModelInfo(execution_context, "master" /* EN_INPUT_MENU_TYPE.Master */)?.model_id) ?? '';
        const confirm_type_value = program_context.data.dmc_map[model_id]?.getValueByReferType('confirm_type');
        const bizz_setting_tf = program_context.sourceData.bizz?.bizz_setting_tf;
        // 일반전표 / 매입전표2 는 v3팝업 오픈
        const form_seq = request.payload.form_seq;
        if (form_seq) {
            const popup_result = await route_handler.openPopupAsync({
                identifier: "IV3WebUploaderPage" /* EN_PAGE_ID.IV3WebUploaderPage */,
                bizz_sid: program_context.data.bizz_sid,
                module: execution_context.view_info.module_name,
                param: { confirm_type: confirm_type_value, form_seq },
            });
            popup_result.message?.callback?.();
            return;
        }
        // 판매의 경우 플래그 On 이면 5.0 웹자료올리기
        if (_.vIsEquals(program_context.data.bizz_sid, 'B_000000E040205') &&
            globalThis.$ECountApp?.app_config?.deploy_flags?.v56_sales_input) {
            const flag_result = await common.RacCommandBuilder.createCommon("/ec56/api/common/action/CheckSalesFlagAction" /* EN_ACTION_ID.ICheckSalesFlagAction */, request.execution_context).executeAsync({
                bizz_sid: program_context.data.bizz_sid,
            });
            if (!flag_result.is_sales_flag_enabled) {
                await request.vmc.alertAsync({ message: $Resx.rex09189 });
                globalThis.$ECount.reloadTopWindow();
                return;
            }
            await OpenWebUploaderUserAction_1._openWebUploaderPopupAsync(request, confirm_type_value);
            return;
        }
        // 매출이거나 업무설정이 적용된 업무는 5.0 웹자료올리기
        else if (_.vIsEquals(program_context.data.bizz_sid, 'B_000000E010301') ||
            (bizz_setting_tf && !_.vIsEquals(program_context.data.bizz_sid, 'B_000000E040205'))) {
            await OpenWebUploaderUserAction_1._openWebUploaderPopupAsync(request, confirm_type_value);
        }
        else {
            //------------------------------------------------------
            // 3.0 웹자료올리기 팝업 오픈
            //------------------------------------------------------
            const popup_result = await route_handler.openPopupAsync({
                identifier: "IV3WebUploaderPage" /* EN_PAGE_ID.IV3WebUploaderPage */,
                bizz_sid: program_context.data.bizz_sid,
                module: execution_context.view_info.module_name,
                param: { confirm_type: confirm_type_value },
            });
            popup_result.message?.callback?.();
        }
    }

static async _openWebUploaderPopupAsync(request, confirm_type_value) {
        const { execution_context } = request;
        const route_handler = execution_context.getFeature("IHandleRouteFeature$V56" /* EN_FEATURE_ID.IHandleRouteFeature */);
        const program_context = execution_context.getProgramContext();
        //------------------------------------------------------
        // 5.0 웹자료올리기 팝업 오픈
        //------------------------------------------------------
        const bizz = program_context.sourceData.bizz;
        let menu_sid = bizz?.menu_sid_map?.["web_upload" /* EN_MENU_TYPE.WebUploader */] ?? program_context.data.menu_sid ?? '';
        // TODO (bjb) - GetCtxBizzSvc._getMenuSidMap() > 같은 메뉴 타입에 대해 I, II 구분할 수 없음 => 임시 하드코딩 처리
        // 매출 2 입력 -> 매출 2 자료올리기
        switch (program_context.data.menu_sid) {
            case 'M_000000E010301': // 매출전표 1
                menu_sid = 'M_000000E510301';
                break;
            case 'M_000000E200534': // 매출전표 2
                menu_sid = 'M_000000N000041';
                break;
        }
        const popup_result = await route_handler.openPopupAsync({
            module: execution_context.view_info.module_name,
            identifier: "IWebUploaderPage" /* EN_PAGE_ID.IWebUploaderPage */,
            bizz_sid: program_context.data.bizz_sid,
            param: {
                bizz_sid: program_context.data.bizz_sid,
                menu_sid,
                menu_type: "upload" /* EN_MENU_TYPE.Upload */,
                menu_nm: execution_context.runtime.page_header_title,
                action_mode: "NEW" /* EN_ACTION_MODE.Create */,
                confirm_type: confirm_type_value,
            },
        }, {
            styleOptions: {
                height: 640,
            },
            title: request.payload.title,
        });
        popup_result.message?.callback?.();
    }
